import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { afterEach, describe, expect, it } from 'vitest';
import { TEMPLATE, writeGame } from './newGame.js';
import { loadGameConfig } from '../gameConfig.js';
import { ITEM_SIZE, MAX_ISOMETRIC_OVERHANG } from '../../shared/constants.js';
import type { Tile } from '../../shared/types.js';

// templates/new-game is generated by its build/, so these hold it to what the
// engine reads rather than to what the script meant to write.

const read = <T>(...parts: string[]): T =>
  JSON.parse(fs.readFileSync(path.join(TEMPLATE, ...parts), 'utf8')) as T;

// Width and height, from the PNG's header.
const pngSize = (...parts: string[]) => {
  const png = fs.readFileSync(path.join(TEMPLATE, ...parts));
  return { width: png.readUInt32BE(16), height: png.readUInt32BE(20) };
};

type Frame = {
  x: number;
  y: number;
  width: number;
  height: number;
  drawWidth: number;
  drawHeight: number;
  anchorX: number;
  anchorY: number;
  piece?: { layer: string };
};

const npcs = read<
  { id: string; sprite: number; itemsToDrop?: { itemId: number }[] }[]
>('game', 'content', 'npcs.json');
const items = read<{ id: number; sprite: number }[]>(
  'game',
  'content',
  'items.json',
);
const { world } = read<{
  world: { respawnTile: { col: number; row: number } };
}>('game', 'game.json');

describe.each(['orthogonal', 'isometric'] as const)(
  'the %s template',
  (orientation) => {
    const [map] = read<{ orientation: string; tiles: Tile[][] }[]>(
      orientation,
      'content',
      'maps.json',
    );
    const tiles = map!.tiles;
    const frames = read<Record<string, Frame>>(
      orientation,
      'assets',
      'tiles.json',
    );
    const atlas = pngSize(orientation, 'assets', 'tiles.png');
    const layout = read<{ width: number; height: number; columns: number }>(
      orientation,
      'assets',
      'sprites.json',
    );
    const sheet = pngSize(orientation, 'assets', 'sprites.png');

    it('is a map of its own projection', () => {
      expect(map!.orientation).toBe(orientation);
    });

    it('lays the ground from ground pieces and the rest from frames the atlas has', () => {
      for (const tile of tiles.flat()) {
        expect(frames[tile.tileIndex]?.piece?.layer).toBe('ground');
        if (tile.maskIndex !== undefined) {
          expect(frames[tile.maskIndex]).toBeDefined();
          expect(frames[tile.maskIndex]?.piece?.layer).not.toBe('ground');
        }
      }
    });

    it('keeps every frame inside tiles.png and within the reach the client allows', () => {
      for (const f of Object.values(frames)) {
        expect(f.x + f.width).toBeLessThanOrEqual(atlas.width);
        expect(f.y + f.height).toBeLessThanOrEqual(atlas.height);
        for (const side of [f.drawWidth, f.drawHeight, f.anchorX, f.anchorY])
          expect(side).toBeLessThanOrEqual(MAX_ISOMETRIC_OVERHANG);
      }
    });

    // The client stacks the characters and every effect sheet into one canvas
    // (graphics/atlas.ts), and iOS Safari draws nothing on a canvas past
    // 4096 x 4096 pixels of area.
    it('fits its characters and effects in one canvas iOS will draw', () => {
      const stacked = [
        sheet,
        ...['items', 'spells', 'arrows', 'attackeffect'].map((name) =>
          pngSize('game', 'assets', `${name}.png`),
        ),
      ];
      const width = Math.max(...stacked.map((s) => s.width));
      const height = stacked.reduce((sum, s) => sum + s.height, 0);
      expect(width * height).toBeLessThanOrEqual(4096 * 4096);
    });

    it('gives every npc a character the sheet has, and spawns only those npcs', () => {
      const perRow = Math.floor(sheet.width / (layout.columns * layout.width));
      const rows = Math.floor(sheet.height / (4 * layout.height));
      for (const npc of npcs) expect(npc.sprite).toBeLessThan(perRow * rows);
      const ids = new Set(npcs.map((n) => n.id));
      for (const tile of tiles.flat())
        if (tile.npcSpawn) expect(ids).toContain(tile.npcSpawn);
    });

    // Props are scattered by a seeded roll, so a change to the seed or the
    // layout could wall a spawn in without anyone looking at the map.
    it('lets a player walk from the respawn point to every npc', () => {
      const seen = new Set<string>();
      const queue = [[world.respawnTile.col, world.respawnTile.row]];
      while (queue.length) {
        const [col, row] = queue.pop()!;
        const key = `${col},${row}`;
        const tile = tiles[row!]?.[col!];
        if (!tile || tile.blocked || seen.has(key)) continue;
        seen.add(key);
        queue.push(
          [col! + 1, row!],
          [col! - 1, row!],
          [col!, row! + 1],
          [col!, row! - 1],
        );
      }
      tiles.forEach((line, row) =>
        line.forEach((tile, col) => {
          if (tile.npcSpawn) expect(seen).toContain(`${col},${row}`);
        }),
      );
    });
  },
);

describe('what every new game gets', () => {
  it('drops only items it defines, each with an icon', () => {
    const icons = pngSize('game', 'assets', 'items.png').width / ITEM_SIZE;
    const ids = new Set(items.map((i) => i.id));
    for (const item of items) expect(item.sprite).toBeLessThan(icons);
    for (const drop of npcs.flatMap((n) => n.itemsToDrop ?? []))
      expect(ids).toContain(drop.itemId);
  });
});

describe('writeGame', () => {
  let dir: string | undefined;
  afterEach(() => {
    if (dir) fs.rmSync(dir, { recursive: true, force: true });
  });

  it('writes a game.json the boot accepts, named after the folder, every sheet and the scripts', () => {
    dir = fs.mkdtempSync(path.join(os.tmpdir(), 'new-game-'));
    const game = path.join(dir, 'my-game');
    writeGame(game);
    const config = loadGameConfig(game);
    expect(config.brand.name).toBe('My Game');
    expect(config.world.respawnTile).toEqual(world.respawnTile);
    for (const sheet of [
      'tiles',
      'sprites',
      'items',
      'spells',
      'arrows',
      'attackeffect',
    ])
      expect(fs.existsSync(path.join(game, 'assets', `${sheet}.png`))).toBe(
        true,
      );
    expect(fs.existsSync(path.join(game, 'scripts', 'example.js'))).toBe(true);
    expect(fs.existsSync(path.join(game, 'build'))).toBe(false);
  });

  // game.json is where an operator reads what this game is made of. A module
  // missing from it runs on whatever its manifest says, on or off by accident.
  // The starter's script talks through dialog and hands out quest. With them
  // off, its npcs offer to talk and say nothing. Quest mails a reward the bag
  // has no room for, and with mail off nobody can collect it.
  it('lists every official module, on only for what the starter script uses', () => {
    dir = fs.mkdtempSync(path.join(os.tmpdir(), 'new-game-'));
    writeGame(dir);
    const installed = fs
      .readdirSync('modules')
      .filter((id) => fs.existsSync(path.join('modules', id, 'module.json')));
    const { modules } = loadGameConfig(dir);
    expect(Object.keys(modules).sort()).toEqual(installed.sort());
    const on = Object.entries(modules)
      .filter(([, entry]) => entry.enabled)
      .map(([id]) => id);
    expect(on.sort()).toEqual(['dialog', 'mail', 'quest']);
  });

  it('takes the name the login screen shows, when given one', () => {
    dir = fs.mkdtempSync(path.join(os.tmpdir(), 'new-game-'));
    writeGame(dir, 'Meadow Quest');
    expect(loadGameConfig(dir).brand.name).toBe('Meadow Quest');
  });

  it('draws the map isometric when asked', () => {
    dir = fs.mkdtempSync(path.join(os.tmpdir(), 'new-game-'));
    writeGame(dir, undefined, 'isometric');
    const [map] = JSON.parse(
      fs.readFileSync(path.join(dir, 'content', 'maps.json'), 'utf-8'),
    );
    expect(map.orientation).toBe('isometric');
  });
});
